import os from 'node:os';
import { isOnline } from '../local-preview/is-online.js';
const externalInterfaces = {
    eth0: [
        {
            address: '203.0.113.5',
            netmask: '255.255.255.0',
            family: 'IPv4',
            mac: '00:00:00:00:00:00',
            internal: false,
            cidr: '203.0.113.5/24',
        },
    ],
};
const internalInterfaces = {
    lo: [
        {
            address: '127.0.0.1',
            netmask: '255.0.0.0',
            family: 'IPv4',
            mac: '00:00:00:00:00:00',
            internal: true,
            cidr: '127.0.0.1/8',
        },
    ],
};
const okResponse = () => ({
    ok: true,
    body: { cancel: vi.fn().mockResolvedValue(undefined) },
});
describe('isOnline', () => {
    beforeEach(() => {
        vi.restoreAllMocks();
        vi.unstubAllGlobals();
    });
    it('returns false without probing when every interface is internal', async () => {
        vi.spyOn(os, 'networkInterfaces').mockReturnValue(internalInterfaces);
        const fetchMock = vi.fn();
        vi.stubGlobal('fetch', fetchMock);
        await expect(isOnline()).resolves.toBe(false);
        expect(fetchMock).not.toHaveBeenCalled();
    });
    it('returns true when one probe succeeds and aborts the other', async () => {
        vi.spyOn(os, 'networkInterfaces').mockReturnValue(externalInterfaces);
        const unhandled = [];
        const onUnhandled = (reason) => {
            unhandled.push(reason);
        };
        process.on('unhandledRejection', onUnhandled);
        vi.stubGlobal('fetch', vi.fn((url, init) => {
            if (String(url).includes('cloudflare')) {
                return new Promise((_resolve, reject) => {
                    init?.signal?.addEventListener('abort', () => {
                        reject(init.signal?.reason ?? new Error('The operation was aborted'));
                    });
                });
            }
            return Promise.resolve(okResponse());
        }));
        await expect(isOnline(1_000)).resolves.toBe(true);
        await new Promise((resolve) => setTimeout(resolve, 20));
        process.off('unhandledRejection', onUnhandled);
        expect(unhandled).toEqual([]);
    });
    it('returns false when every probe fails', async () => {
        vi.spyOn(os, 'networkInterfaces').mockReturnValue(externalInterfaces);
        vi.stubGlobal('fetch', vi.fn(async () => ({ ok: false, status: 503 })));
        await expect(isOnline()).resolves.toBe(false);
    });
    it('aborts a hung probe and does not surface the abort as an unhandled rejection', async () => {
        vi.spyOn(os, 'networkInterfaces').mockReturnValue(externalInterfaces);
        const unhandled = [];
        const onUnhandled = (reason) => {
            unhandled.push(reason);
        };
        process.on('unhandledRejection', onUnhandled);
        vi.stubGlobal('fetch', vi.fn((_url, init) => new Promise((_resolve, reject) => {
            init?.signal?.addEventListener('abort', () => {
                reject(init.signal?.reason ?? new Error('The operation was aborted'));
            });
        })));
        await expect(isOnline(20)).resolves.toBe(false);
        await new Promise((resolve) => setTimeout(resolve, 30));
        process.off('unhandledRejection', onUnhandled);
        expect(unhandled).toEqual([]);
    });
});
